function Die(sides)
{
   this.numSides = sides;
   this.numRolls = 0;
   this.roll = roll;   // gán method
}
function roll()
{
    this.numRolls++;
    return Math.floor(Math.random() * this.numSides) + 1;
}

die6 = new Die(6);
die8 = new Die(8);
var r = die6.roll();
document.write(die6.numRolls);   // 1

function Point(xcoord, ycoord) {
    this.x = xcoord;
    this.y = ycoord;
}
function distance(x2, y2) {
    function sqr(x) { return x * x; }
    return Math.sqrt(sqr(this.x - x2) + sqr(this.y - y2));
}
myPoint = new Point(3, 5);
distance.call(myPoint, 0, 1);     // 5
distance.apply(myPoint, [0, 1]);  // 5

